"""Blender entry point: bake all 3D sprite frames for the Bot Bastion pack (original, generated by project scripts).
    blender -b --python bb_bake.py -- <rawdir> [bots,aegis,core,enemies,proj,sectors]
Writes <rawdir>/<name>.png (2x supersampled, transparent) and <rawdir>/index.<group>.json per group."""
import os, sys, json, math
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from bb_kit import *
import bb_units as U

R = math.radians


def flush(group):
    global INDEX
    json.dump(INDEX, open(os.path.join(OUT, f"index.{group}.json"), "w"), indent=0)
    print("GROUP", group, len(INDEX))
    INDEX.clear()


def spin(o, k, roll=0.0):
    o.rotation_euler = (0, roll, R(45 * k - 90))


BOT_SCALE = 0.44
BOT_CELL = 160

# ------------------------------------------------------------------ bots
if want("bots"):
    for nm, fn in (("picket", U.picket), ("lobber", U.lobber), ("haze", U.haze)):
        for L in range(1, 6):
            base, head = fn(L)
            show_only([base])
            shoot(f"{nm}_L{L}_base", BOT_CELL, BOT_CELL, BOT_SCALE, 0.7, dict(group=nm, part="base", level=L, facing=0, anim="static", outline=True))
            show_only([head])
            for k in range(8):
                spin(head, k)
                shoot(f"{nm}_L{L}_head_f{k}", BOT_CELL, BOT_CELL, BOT_SCALE, 0.7, dict(group=nm, part="head", level=L, facing=k, anim="static", outline=True))
            purge()
    for L in range(1, 6):
        base = U.tender(L)
        show_only([base])
        shoot(f"tender_L{L}_base", BOT_CELL, BOT_CELL, BOT_SCALE, 0.7, dict(group="tender", part="base", level=L, facing=0, anim="static", outline=True))
        for f in range(4):  # 6 petals => 60 deg period, 4 frames of 15 deg loop seamlessly
            rot = U.tender_rotor(L, 15 * f)
            show_only([rot])
            shoot(f"tender_L{L}_rotor_{f}", BOT_CELL, BOT_CELL, BOT_SCALE, 0.7, dict(group="tender", part="rotor", level=L, facing=0, anim="spin", frame=f, outline=True))
        purge()
    for L in range(1, 6):
        sk = U.skiff(L)
        show_only([sk])
        for k in range(8):
            spin(sk, k)
            shoot(f"skiff_L{L}_f{k}", BOT_CELL, BOT_CELL, 0.42, 0.6, dict(group="skiff", part="body", level=L, facing=k, anim="static", outline=True, flying=True))
        purge()
    flush("bots")

# ------------------------------------------------------------------ aegis + core
if want("aegis"):
    a = U.aegis()
    show_only([a])
    shoot("aegis_base", BOT_CELL, BOT_CELL, BOT_SCALE, 0.7, dict(group="aegis", part="base", level=1, facing=0, anim="static", outline=True))
    purge()
    flush("aegis")

if want("core"):
    for s in range(4):
        c = U.core(s)
        show_only([c])
        shoot(f"core_s{s}", 300, 340, 0.5, 1.6, dict(group="core", part="body", level=1, facing=0, anim="state", frame=s, outline=True))
        purge()
    flush("core")

# ------------------------------------------------------------------ enemies: 8 facings x 4 tumble frames
ENEMIES = [("drifter", U.drifter, 0.42, 128, 0.6), ("darter", U.darter, 0.4, 128, 0.5), ("plater", U.plater, 0.42, 128, 0.7),
           ("splitter", U.splitter, 0.42, 128, 0.6), ("bit", U.bit, 0.42, 96, 0.45), ("courier", U.courier, 0.42, 128, 0.8)]
TUMBLE = [(-0.07, 0.0), (0.0, 0.05), (0.07, 0.0), (0.0, 0.05)]  # (roll rad about forward axis, bob in model units)

if want("enemies"):
    for nm, fn, gs, cell, lz in ENEMIES:
        o = fn()
        show_only([o])
        for k in range(8):
            for f, (roll, bob) in enumerate(TUMBLE):
                o.rotation_euler = (0, roll, R(45 * k - 90))
                o.location = (0, 0, bob)
                shoot(f"{nm}_f{k}_m{f}", cell, cell, gs, lz, dict(group=nm, part="body", level=1, facing=k, anim="move", frame=f, outline=True))
        purge()
    for skin in U.BEHEMOTH_SKINS:
        o = U.behemoth(skin)
        show_only([o])
        for k in range(8):
            for f, (roll, bob) in enumerate(TUMBLE):
                o.rotation_euler = (0, roll * 0.5, R(45 * k - 90))
                o.location = (0, 0, bob * 0.6)
                shoot(f"behemoth_{skin}_f{k}_m{f}", 256, 256, 0.8, 1.0, dict(group="behemoth_" + skin, part="body", level=1, facing=k, anim="move", frame=f, outline=True))
        purge()
    flush("enemies")

# ------------------------------------------------------------------ projectiles
if want("proj"):
    for kind in ("pew", "skiff", "hiss"):
        o = U.bolt(kind)
        show_only([o])
        for k in range(8):
            o.rotation_euler = (0, 0, R(45 * k - 90))
            shoot(f"proj_{kind}_f{k}", 64, 64, 1.0, 0.0, dict(group="proj_" + kind, part="body", level=1, facing=k, anim="fly", outline=False, kind="centered"))
        purge()
    o = U.shell()
    show_only([o])
    shoot("proj_shell", 64, 64, 1.0, 0.0, dict(group="proj_shell", part="body", level=1, facing=0, anim="fly", outline=False, kind="centered"))
    purge()
    o = U.crate()
    show_only([o])
    for f in range(6):
        o.rotation_euler = (0, 0, R(60 * f))
        shoot(f"crate_{f}", 96, 96, 1.0, 0.1, dict(group="crate", part="body", level=1, facing=0, anim="spin", frame=f, outline=True))
    purge()
    flush("proj")

if want("sectors"):
    import bb_sectors
    bb_sectors.run()
    flush("sectors")
